pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint8 actorSeed) public {
        // Restrict deposit to >0 and collect to <=deposit + initial, plausible range
        vm.assume(depositAmount > 0 && depositAmount < 1000 ether);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        // Derive an actor from the seed, ensuring it's not zero
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0));

        // Initialize contract for use
        c.Initialized();

        // Deposit via Deposit()
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Attempt to collect
        vm.prank(actor);
        try c.Collect(collectAmount) { } catch { }

        // The invariant: the contract's balance + total collected by actor should equal total deposited,
        // i.e., actor's balance in mapping (deposit - collect if successful, else deposit) must reflect deposits.
        // In the correct contract, after a successful collect, balances[actor] == depositAmount - collectAmount.
        // In the buggy contract, balances[actor] is never updated, so it remains 0, breaking this equality.
        uint256 expectedBalance = depositAmount;
        if (collectAmount <= depositAmount && collectAmount >= 1 ether) {
            // collect succeeds in both if conditions: balances>=MinSum(1 ether) and balances>=collectAmount
            expectedBalance = depositAmount - collectAmount;
        }
        assertEq(c.balances(actor), expectedBalance);
    }
}

