pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        depositAmount = bound(depositAmount, 1, 1000 ether);
        collectAmount = bound(collectAmount, 1, 1000 ether);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract
        c.Initialized();

        // Set MinSum so collect is allowed
        c.SetMinSum(0);

        // Deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Collect
        vm.prank(actor);
        c.Collect(collectAmount);

