pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address depositor) public {
        // Keep amounts reasonable and ensure depositor is not a precompile/system address
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= 1000 ether);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));
        vm.assume(depositor != address(c));
        vm.assume(depositor.code.length == 0); // EOA, no contract

        // Initialize contract and set MinSum to zero so any amount can be collected
        c.Initialized();
        c.SetMinSum(0);

        // Record balance before deposit
        uint256 initialBalance = c.balances(depositor);

        // Deposit
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Collect
        vm.prank(depositor);
        c.Collect(collectAmount);

        // Assert: balance = initialBalance + depositAmount - collectAmount
        uint256 finalBalance = c.balances(depositor);
        assertTrue(finalBalance == initialBalance + depositAmount - collectAmount);
    }
}

